pub const ToolDef = registry.ToolDef;

/// Composes tool arguments from a JSON body with an optional `{s}` slot.
///
/// The JSON braces must be DOUBLED (`{{` `}}`) because `allocPrint` reads a `{` as
/// the start of a placeholder and `{"symbol":` is not one. Four tests in a row
/// failed on that, each one looking like a bug in the tool under test rather than
/// in the test.
pub fn jsonArgs(arena: std.mem.Allocator, comptime body: []const u8, args: anytype) ![]const u8 {
    return std.fmt.allocPrint(arena, body, args);
}

pub fn writeTmp(arena: std.mem.Allocator, path: []const u8, body: []const u8) ![]const u8 {
    return std.fmt.allocPrint(arena,
        \\{{"path":"{s}","content":"{s}"}}
    , .{ path, body });
}

/// Tools that can run at the same time as each other.
///
/// Every one of these only READS: `read`/`grep`/`glob`/`list_files` see the
/// filesystem, `web_*` see the network, and none of them can observe or change
/// another. That is the whole requirement — not "they are cheap", not "they
/// usually do not conflict" — because `execToolCalls` runs a batch of these
/// concurrently and a tool that writes, or that the model expects to see the
/// world after, has to be in the serial part or the result is a race.
///
/// `bash` is NOT here even when it is `cat file`: a `bash` can write, and the
/// model may have asked for two `bash` in a row where the second reads what the
/// first wrote.
pub const isParallelSafe = registry.isParallelSafe;

/// Declares the tools to the LLM (OpenAI format). Static: 0 allocs per request.
///
/// Composed from the per-tool prompt modules, in `defs` order: the tool TABLE and the
/// tool SCHEMA are the same list written twice, and the test below fails the day one of
/// them gains a tool the other has not. Each module owns its own prose and parameters,
/// so adding a rule is a one-file edit that cannot break another tool's text.
pub const toolsJson = registry.toolsJson;

/// Read-only mode (`shift+tab`): the toolset that cannot change the machine.
///
/// It is EXACTLY the tools that do not ask for permission — the same policy stated
/// once as the permission table (`needsPermission`) and once as a schema, with a test
/// below that fails when the two disagree.
///
/// It used to be a second, hand-maintained copy of eighteen entries of `toolsJson()`.
/// Those copies are gone: a description improved in one array and not in the other was
/// a tool that read differently depending on the mode it was offered in.
pub const toolsJsonReadOnly = registry.toolsJsonReadOnly;

test "the read-only schema is exactly the tools that do not ask for permission" {
    // The day these two disagree, the model is either offered a tool in read-only mode
    // that stops at a permission dialog (the mode exists so that nothing can happen)
    // or denied one that could not have done anything anyway.
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const ro = std.json.parseFromSliceLeaky(std.json.Value, arena_state.allocator(), toolsJsonReadOnly(), .{}) catch
        return error.BadSchema;
    if (ro != .array) return error.BadSchema;
    for (defs) |d| {
        var in_readonly = false;
        for (ro.array.items) |item| {
            const n = item.object.get("function").?.object.get("name").?.string;
            if (std.mem.eql(u8, n, d.name)) in_readonly = true;
        }
        if (in_readonly == needsPermission(d.name)) {
            std.debug.print(
                "{s}: the read-only schema and the permission table disagree (in the schema: {}, asks permission: {})\n",
                .{ d.name, in_readonly, needsPermission(d.name) },
            );
            return error.ReadOnlySchemaDrift;
        }
    }
}

/// Does this tool need to ask the user before running it?
///
/// `web_fetch` and `web_search` do NOT ask: they are reads, they write nothing, and
/// a dialog for every internet query turns the agent loop into an interrogation.
/// Same criterion as `read` or `grep`.
///
/// The three new ones are in the no-permission group for different reasons, and
/// it is worth being explicit about each:
///
/// - `ask` asks by DESIGN. Putting it behind a permission dialog would be two
///   dialogs for one question, and the second would be a yes/no about the first.
/// - `skill` only reads a file and returns text.
/// - `bash_output`/`bash_kill` only talk to processes THIS TURN started, whose
///   creation already went through the `bash` permission. Asking again would be
///   asking twice about the same command.
///
/// `task` DOES ask: a subagent spends tokens and can read the whole repo, so it
/// goes through the same dialog as `web_fetch` would if we had not decided reads
/// are free. What makes it acceptable is that it cannot write.
pub const needsPermission = registry.needsPermission;

/// The tools ONE CALL needs permission for.
///
/// For every tool but `batch` it is the tool itself. For `batch` it is the
/// union of the tools its steps are calls to: a batch of reads asks for
/// nothing, and a batch with a write step asks for exactly what that write
/// would have asked. The union is the whole safety argument of the tool.
pub const callPermissionTools = registry.callPermissionTools;

/// Does this call change a file? A batch is decided by its steps.
pub const callWrites = registry.callWrites;

/// The files this call would write or edit. A batch can be several.
pub const callTouchedPaths = registry.callTouchedPaths;

/// What the permission dialog says about a batch: what it would do, and to
/// which files.
pub const batchPermissionDetail = registry.batchPermissionDetail;
/// The paths of a call that the sensitive-path rule would refuse.
pub const riskyPaths = registry.riskyPaths;
/// The subjects a permission rule is matched against.
pub const callSubjects = registry.callSubjects;

/// Runs a tool with JSON args. Returns the (truncated) result —
/// `arena` memory, valid until the arena is freed.
///
/// `bg` is the background-process registry, and it is a PARAMETER rather than a
/// global because it lives in the `Model`: two `Model`s (the real one and the
/// ones the tests build) must not share a list of running processes. `null` means
/// "no registry", which only happens in the tests, and a `bash` that asks to run
/// in the background then gets an error that says exactly that instead of
/// silently running in the foreground (which would look like `run_in_background`
/// works).
///
/// `cache` is the read cache, for the same reason and with the same shape: it
/// lives in the `Model`, `read` runs in parallel with other reads so the lock is
/// inside the cache, and `null` (which is what the tests pass) means every read
/// sends its body as always — the behaviour we want to be able to test both ways.
pub fn execute(
    io: std.Io,
    name: []const u8,
    args_json: []const u8,
    arena: std.mem.Allocator,
    bg: ?*bgproc.Registry,
    cache: ?*readcache.Cache,
) ![]const u8 {
    return executeWith(io, name, args_json, arena, bg, cache, null);
}

/// `execute` plus the session's task graph.
///
/// A second entry point rather than a seventh parameter on `execute`, for the same
/// reason `chat.streamChatDetail` sits next to `streamChat`: the callers that have no
/// session state at all (every test, `zig build tool-test`, the probes) should not
/// have to say `null` three times to call a tool, and the two runners that DO have a
/// session say what they mean explicitly. The parameter is the honest shape — the
/// store belongs to a session, and a module global would be a lie about when two
/// things are the same.
///
/// `null` means "this caller has no task list", which the five task tools answer with
/// `error.NoTaskStore` and a sentence, never with an empty list that looks like a
/// real one.
pub fn executeWith(
    io: std.Io,
    name: []const u8,
    args_json: []const u8,
    arena: std.mem.Allocator,
    bg: ?*bgproc.Registry,
    cache: ?*readcache.Cache,
    tasks: ?*taskstore.Store,
) ![]const u8 {
    const parsed = try std.json.parseFromSliceLeaky(std.json.Value, arena, args_json, .{});
    if (parsed != .object) return error.BadArgs;
    const obj = parsed.object;

    if (std.mem.eql(u8, name, "read")) {
        return read_tool.toolRead(io, obj, arena, cache);
    } else if (std.mem.eql(u8, name, "write")) {
        return write_tool.toolWrite(io, obj, arena);
    } else if (std.mem.eql(u8, name, "edit")) {
        return edit_tool.toolEdit(io, obj, arena);
    } else if (std.mem.eql(u8, name, "notebook_edit")) {
        return notebook_tool.toolNotebookEdit(io, obj, arena);
    } else if (std.mem.eql(u8, name, "bash")) {
        return bash_tool.toolBash(io, obj, arena, bg);
    } else if (std.mem.eql(u8, name, "glob")) {
        return glob_tool.toolGlob(io, obj, arena);
    } else if (std.mem.eql(u8, name, "grep")) {
        return grep_tool.toolGrep(io, obj, arena);
    } else if (std.mem.eql(u8, name, "refs")) {
        return refs_tool.toolRefs(io, obj, arena);
    } else if (std.mem.eql(u8, name, "rename")) {
        return rename_tool.toolRename(io, obj, arena);
    } else if (std.mem.eql(u8, name, "check")) {
        return check_tool.toolCheck(io, obj, arena, bg, arena);
    } else if (std.mem.eql(u8, name, "git_status")) {
        return git_tool.toolGitStatus(io, arena);
    } else if (std.mem.eql(u8, name, "git_diff")) {
        return git_tool.toolGitDiff(io, obj, arena);
    } else if (std.mem.eql(u8, name, "git_log")) {
        return git_tool.toolGitLog(io, obj, arena);
    } else if (std.mem.eql(u8, name, "git_branch")) {
        return git_tool.toolGitBranch(io, arena, common.getStr(obj, "action") orelse "list", common.getStr(obj, "name") orelse "");
    } else if (std.mem.eql(u8, name, "git_add")) {
        return git_tool.toolGitAdd(io, arena, common.getStrList(obj, "paths"));
    } else if (std.mem.eql(u8, name, "git_commit")) {
        return git_tool.toolGitCommit(io, arena, common.getStr(obj, "message") orelse "");
    } else if (std.mem.eql(u8, name, "git_stash")) {
        return git_tool.toolGitStash(io, arena, common.getStr(obj, "action") orelse "push");
    } else if (std.mem.eql(u8, name, "list_files")) {
        return list_files_tool.toolListFiles(io, obj, arena);
    } else if (std.mem.eql(u8, name, "web_fetch")) {
        return web_tool.toolWebFetch(io, obj, arena);
    } else if (std.mem.eql(u8, name, "web_search")) {
        return web_tool.toolWebSearch(io, obj, arena);
    } else if (std.mem.eql(u8, name, "think")) {
        return think_tool.toolThink(obj, arena);
    } else if (std.mem.eql(u8, name, "todo")) {
        return todo_tool.toolTodo(obj, arena);
    } else if (std.mem.eql(u8, name, "task_create")) {
        return tasks_tool.toolTaskCreate(io, tasks, obj, arena);
    } else if (std.mem.eql(u8, name, "task_get")) {
        return tasks_tool.toolTaskGet(tasks, obj, arena);
    } else if (std.mem.eql(u8, name, "task_list")) {
        return tasks_tool.toolTaskList(tasks, arena);
    } else if (std.mem.eql(u8, name, "task_update")) {
        return tasks_tool.toolTaskUpdate(io, tasks, obj, arena);
    } else if (std.mem.eql(u8, name, "task_stop")) {
        return tasks_tool.toolTaskStop(io, tasks, obj, arena);
    } else if (std.mem.eql(u8, name, "goal")) {
        return goal_tool.toolGoal(obj, arena);
    } else if (std.mem.eql(u8, name, "bash_output")) {
        return bg_tool.toolBashOutput(obj, arena, bg);
    } else if (std.mem.eql(u8, name, "bash_kill")) {
        return bg_tool.toolBashKill(obj, arena, bg, io);
    } else if (std.mem.eql(u8, name, "sleep")) {
        return sleep_tool.toolSleep(io, obj, arena);
    } else if (std.mem.eql(u8, name, "batch")) {
        return batch_tool.toolBatch(io, obj, arena);
    } else if (std.mem.eql(u8, name, "lsp")) {
        return lsp_tool.toolLsp(io, obj, arena);
    }
    return error.UnknownTool;
}

// ── what the rest of the repo imports ───────────────────────────
//
// `agent.zig` and the tests used to import one `tools.zig` and call these seven
// names. They are `pub` HERE already, so the split needs no re-export shim: the
// only thing that changed is which file the code lives in. Anything else that
// wants to reach past the dispatcher imports the tool file directly.

pub const setAutoBackground = bg_tool.setAutoBackground;

pub const defs = registry.defs;

// ── the two names that belong to no single tool ───────────────
//
// `describeError` lives with the errors and `setAutoBackground` with the
// background rules, but both are called through this module by `agent.zig`. They
// are re-exported rather than reached for directly so that the tool files stay
// replaceable behind the dispatcher.

pub const describeError = errors_tool.describeError;

test "needsPermission" {
    try std.testing.expect(!needsPermission("read"));
    try std.testing.expect(needsPermission("write"));
    try std.testing.expect(needsPermission("bash"));
}

test "toolsJson is valid JSON and has one entry per tool" {
    const arena = std.testing.allocator;
    var arena_state = std.heap.ArenaAllocator.init(arena);
    defer arena_state.deinit();
    const v = std.json.parseFromSliceLeaky(std.json.Value, arena_state.allocator(), toolsJson(), .{}) catch {
        return error.TestUnexpectedResult;
    };
    try std.testing.expect(v == .array);
    // The count comes from `defs`, not from a hand-written number: adding a tool
    // without declaring it in the JSON (or the other way round) fails here instead of leaving
    // the model with a tool that does not exist.
    try std.testing.expectEqual(defs.len, v.array.items.len);
    for (v.array.items) |item| {
        const fname = item.object.get("function").?.object.get("name").?.string;
        var found = false;
        for (defs) |d| {
            if (std.mem.eql(u8, d.name, fname)) found = true;
        }
        try std.testing.expect(found);
    }
}

test "the unknown-tool message names every tool in defs, not a hand-kept subset" {
    // The message is the one place the model is handed the whole vocabulary, and it is
    // hand-written. It was already wrong: it named sixteen of the twenty-nine tools and
    // silently omitted the git ones, `refs`, `rename`, `check`, `lsp`, `review` and
    // `goal`, so a model that reached for a tool that exists could be told it does not.
    // `defs` is the table; this test makes the message a view of it instead.
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const msg = errors_tool.describeError(arena_state.allocator(), error.UnknownTool, "serch", "{}");
    for (defs) |d| {
        if (std.mem.indexOf(u8, msg, d.name) == null) {
            std.debug.print("the unknown-tool message never names {s}\n", .{d.name});
            return error.ToolNotListed;
        }
    }
}

