    const out = try execute(std.testing.io, "bash",
        \\{"command":"echo hello","timeout_seconds":10}
    , arena, null, null);
    try std.testing.expect(std.mem.indexOf(u8, out, "hello") != null);
    // A notice on every call is worse than none: the model would learn to ignore it.
    try std.testing.expect(std.mem.indexOf(u8, out, "output cut") == null);
    try std.testing.expect(std.mem.indexOf(u8, out, "exit=0") != null);
}

test "bash: a command that only prints a LOT does not leave a grandchild behind" {
    // The kill has to be the process GROUP, not the pid: `/bin/sh -c "a && b"` has
    // children and killing only the shell leaves the grandchild writing into a pipe
    // nobody reads. This is the same contract `tools/esc_kill_pty.py` checks for ESC,
    // and it is the reason the truncation path can return at all instead of hanging.
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    // `yes` never stops on its own, so a truncation that did not kill it would hang
    // here for the full timeout instead of returning.
    const t0 = std.Io.Timestamp.now(std.testing.io, .real).toNanoseconds();
    const out = try execute(std.testing.io, "bash",
        \\{"command":"yes zode","timeout_seconds":30}
    , arena, null, null);
    const elapsed_ms = @as(f64, @floatFromInt(std.Io.Timestamp.now(std.testing.io, .real).toNanoseconds() - t0)) / 1e6;

    try std.testing.expect(std.mem.indexOf(u8, out, bg_tool.foreground_truncation_notice) != null);
    // Nowhere near the 30 s timeout: the point of the cap is that it returns.
    try std.testing.expect(elapsed_ms < 5000);
}

test "edit: a hunk that would write the file back unchanged is refused" {
    // It used to succeed: the file came out byte-identical, the tool reported a change,
    // and the thing the model meant to edit was never touched. A no-op dressed as an
    // edit is worse than an error, because nothing looks wrong.
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    // Its own directory creation: the suite usually finds `/tmp/opencode` already
    // there from another test, and a test that needs it is a test that fails alone.
    std.Io.Dir.cwd().createDirPath(std.testing.io, "/tmp/opencode") catch {};
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{
        .sub_path = "/tmp/opencode/edit-noop.txt",
        .data = "alpha\nbeta\n",
    });

    const out = try execute(std.testing.io, "edit",
        \\{"path":"/tmp/opencode/edit-noop.txt","old_string":"beta","new_string":"beta"}
    , arena, null, null);
    try std.testing.expect(std.mem.indexOf(u8, out, "identical") != null);

    // And the file is untouched, which is the half that matters: "nothing was written"
    // has to mean nothing.
    const after = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, "/tmp/opencode/edit-noop.txt", arena, .limited(4096));
    try std.testing.expectEqualStrings("alpha\nbeta\n", after);
}

test "a failed edit says WHICH of the three failures it was, and never says nothing" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    // A TAB where the patch has four spaces: the most common way a patch written from
    // memory fails. Absolute paths under `/tmp/opencode`, which is what every other
    // test in this file does — a relative path is resolved against the cwd of the test
    // binary and the failure looks like "the tool is broken".
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{
        .sub_path = "/tmp/opencode/edit-hint-1.txt",
        .data = "pub fn f() void {\n\tx += 1;\n}\n",
    });

    // Through `allocPrint`, like every other `edit` test here: `{{` is how a format
    // string spells a literal brace, and a plain `\\`-string would need the braces
    // single AND would still carry the escaping backslash.
    const args = try std.fmt.allocPrint(arena,
        \\{{"files":[{{"path":"/tmp/opencode/edit-hint-1.txt","old_string":"    x += 1;","new_string":"\tx += 2;"}}]}}
    , .{});
    const out = try execute(std.testing.io, "edit", args, arena, null, null);

    // The three things the model needs and did not have before: WHAT is wrong, WHERE it
    // is, and WHAT it sent. Before this the only thing it had was the path and the
    // first 80 bytes, which cost it a whole iteration to act on.
    try std.testing.expect(std.mem.indexOf(u8, out, "SPACING") != null);
    try std.testing.expect(std.mem.indexOf(u8, out, "x += 1;") != null);
    try std.testing.expect(std.mem.indexOf(u8, out, "You sent:") != null);
    // The familiar phrase is still the OPENING, because the schema and another test
    // use it; what is new is the sentence and the text after it.
    try std.testing.expect(std.mem.indexOf(u8, out, "old_string not found in") != null);
    // And it is no longer JUST those words: the old message was the path plus 80 bytes.
    try std.testing.expect(out.len > 200);
}

